 * Rebuilds the search index for one organization; used after a bulk import or an index drift alarm.
 *
 * Must call (do not reimplement): indexIssue, indexComment, indexProject
 */
import { createLogger } from "@/lib/logger";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import {
  indexComment,
  indexIssue,
  indexProject,
} from "@/server/services/search-service";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { SearchSubjectKind } from "@/server/repositories/search-repository";
import type { OrgId, Page } from "@/types/common";

/** Rows read per page while walking the org's content. */
const PAGE_SIZE = 100;

const logger = createLogger("search-reindex-job");

/**
 * Walks one tenant's live projects, issues and comments and re-upserts every
 * document. Scoped to a single org on purpose: a full-fleet reindex is a
 * sequence of these, so one slow tenant cannot stall the rest.
 *
 * Only live content is indexed: archived projects and issues are skipped, as
 * are deleted comments and every comment on an archived issue. A live reply
 * under a deleted parent is still indexed — each comment is judged on its own
 * row. Documents that were in the index before the walk but no longer belong
 * to live content are dropped once the walk has completed, and duplicate rows
 * for one subject are collapsed, so the rebuild is idempotent and repairs
 * drift.
 */
export async function runSearchReindexJob(orgId: OrgId): Promise<JobResult> {
  return runJob("search-reindex", async (result) => {
    // Snapshot before walking: anything indexed by the live listeners while
    // the rebuild runs is newer than the snapshot and never pruned.
    const snapshot = await collapseDuplicates(orgId);

    const live = new Set<string>();
    let walkComplete = true;

    for await (const project of eachPage((cursor) =>
      projectRepo.listProjects({
        orgId,
        limit: PAGE_SIZE,
        cursor,
        includeArchived: false,
      }),
    )) {
      live.add(documentKey("project", project.id));
      try {
        await indexProject(orgId, project);
        result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to index project", {
          projectId: project.id,
          reason: reasonOf(error),
        });
      }
    }

    for await (const issue of eachPage((cursor) =>
      issueRepo.listIssues({
        orgId,
        limit: PAGE_SIZE,
        cursor,
        includeArchived: false,
      }),
    )) {
      live.add(documentKey("issue", issue.id));
      try {
        await indexIssue(orgId, issue);
        result.processed += 1;
      } catch (error) {
        result.failed += 1;
        logger.error("failed to index issue", {
          issueId: issue.id,
          reason: reasonOf(error),
        });
      }

      try {
        for await (const comment of eachPage((cursor) =>
          commentRepo.listCommentsPage({
            orgId,
            issueId: issue.id,
            limit: PAGE_SIZE,
            cursor,
            includeArchived: false,
          }),
        )) {
          live.add(documentKey("comment", comment.id));
          try {
            await indexComment(orgId, comment);
            result.processed += 1;
          } catch (error) {
            result.failed += 1;
            logger.error("failed to index comment", {
              commentId: comment.id,
              reason: reasonOf(error),
            });
          }
        }
      } catch (error) {
        // Without the full comment list there is no telling which comment
        // documents are stale, so the prune below is skipped this run.
        walkComplete = false;
        result.failed += 1;
        logger.error("failed to list comments", {
          issueId: issue.id,
          reason: reasonOf(error),
        });
      }
    }

    if (!walkComplete) {
      logger.warn("walk incomplete; stale documents left in place", { orgId });
      return;
    }

    const stale = snapshot
      .filter((doc) => !live.has(documentKey(doc.subjectKind, doc.subjectId)))
      .map((doc) => doc.id);
    await searchRepo.deleteSearchDocumentsById(orgId, stale);
  });
}

/**
 * Drops every duplicate row for one subject but the first, so the upserts in
 * the walk leave exactly one document per subject. Returns the survivors.
 */
async function collapseDuplicates(
  orgId: OrgId,
): Promise<readonly searchRepo.SearchDocumentKey[]> {
  const docs = await searchRepo.listSearchDocumentKeys(orgId);
  const seen = new Set<string>();
  const kept: searchRepo.SearchDocumentKey[] = [];
  const duplicates: string[] = [];

  for (const doc of docs) {
    const key = documentKey(doc.subjectKind, doc.subjectId);
    if (seen.has(key)) {
      duplicates.push(doc.id);
      continue;
    }
    seen.add(key);
    kept.push(doc);
  }

  await searchRepo.deleteSearchDocumentsById(orgId, duplicates);
  return kept;
}

/** Follows a cursor listing to its end, one page at a time. */
async function* eachPage<T>(
  fetchPage: (cursor: string | null) => Promise<Page<T>>,
): AsyncGenerator<T> {
  let cursor: string | null = null;
  do {
    const page: Page<T> = await fetchPage(cursor);
    yield* page.items;
    if (page.nextCursor === cursor) break;
    cursor = page.nextCursor;
  } while (cursor !== null);
}

function documentKey(kind: SearchSubjectKind, subjectId: string): string {
  return `${kind}:${subjectId}`;
}

function reasonOf(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

