import { beforeAll, describe, expect, it } from "vitest";
import { emit } from "@/lib/event-bus";
import { createIssueSchema } from "@/schemas/issue";
import { createProjectSchema } from "@/schemas/project";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import { registerSearchListeners } from "@/server/services/search-service";
import { ALICE, ORG_A, ORG_B, BOB } from "./helpers/factories";
import { seedTwoTenants, setupTestDb } from "./helpers/db";

const hits = async (orgId: typeof ORG_A, q: string, kinds: ("issue" | "comment" | "project")[] = []) =>
  (await searchRepo.searchDocuments({ orgId, q, kinds, limit: 100, cursor: null } as never)).total;

async function mkProject(orgId: typeof ORG_A, name: string, slug: string, key: string) {
  const p = await projectRepo.insertProject(createProjectSchema.parse({ orgId, name, slug, key }));
  await emit("project.created", { orgId, projectId: p.id } as never);
  return p;
}
async function mkIssue(orgId: typeof ORG_A, projectId: string, title: string, author = ALICE) {
  const n = await issueRepo.nextIssueNumber(orgId, projectId as never);
  const i = await issueRepo.insertIssue(createIssueSchema.parse({ orgId, projectId, title }), author, n);
  await emit("issue.created", { orgId, issueId: i.id } as never);
  return i;
}
async function mkComment(orgId: typeof ORG_A, issueId: string, body: string, parentId: string | null = null, author = ALICE) {
  const c = await commentRepo.insertComment({ orgId, issueId: issueId as never, body, parentId: parentId as never, mentionedUserIds: [] }, author);
  await emit("comment.created", { orgId, commentId: c.id } as never);
  return c;
}

describe("scratch", () => {
  beforeAll(async () => {
    await setupTestDb();
    await seedTwoTenants();
    registerSearchListeners();
  });

  it("works end to end", async () => {
    const pa = await mkProject(ORG_A, "Alpha Proj", "alpha", "ALP");
    const pb = await mkProject(ORG_B, "Beta Proj", "beta", "BET");
    const archivedProject = await mkProject(ORG_A, "Gone Proj", "gone", "GON");
    await projectRepo.archiveProject(ORG_A, archivedProject.id);

    for (let i = 0; i < 230; i++) await mkIssue(ORG_A, pa.id, `BulkIssue ${i}`);
    const long = await mkIssue(ORG_A, pa.id, "LongDiscussion");
    for (let i = 0; i < 230; i++) await mkComment(ORG_A, long.id, `LongComment ${i}`);

    const thread = await mkIssue(ORG_A, pa.id, "ThreadIssue");
    const parent = await mkComment(ORG_A, thread.id, "ParentMarker");
    const reply = await mkComment(ORG_A, thread.id, "ReplyMarker", parent.id);
    const nested = await mkComment(ORG_A, thread.id, "NestedMarker", reply.id);
    await commentRepo.archiveComment(ORG_A, parent.id);
    await emit("comment.deleted", { orgId: ORG_A, commentId: parent.id, issueId: thread.id } as never);

    expect(await commentRepo.countComments(ORG_A, thread.id)).toBe(2);
    expect(await hits(ORG_A, "ParentMarker")).toBe(0);
    expect(await hits(ORG_A, "ReplyMarker")).toBe(1);
    expect(await hits(ORG_A, "ThreadIssue")).toBe(1);

    const doomed = await mkIssue(ORG_A, pa.id, "DoomedIssue");
    const dc = await mkComment(ORG_A, doomed.id, "DoomedComment");
    await mkComment(ORG_A, doomed.id, "DoomedReply", dc.id);
    const bIssue = await mkIssue(ORG_B, pb.id, "DoomedComment other org", BOB);
    await mkComment(ORG_B, bIssue.id, "DoomedComment in B", null, BOB);
    await issueRepo.archiveIssue(ORG_A, doomed.id);
    await emit("issue.archived", { orgId: ORG_A, issueId: doomed.id, projectId: pa.id } as never);
    expect(await hits(ORG_A, "Doomed")).toBe(0);
    expect(await hits(ORG_B, "DoomedComment")).toBe(2);

    // drift: stale docs + duplicates
    const stale = await mkComment(ORG_A, thread.id, "SilentlyDeleted");
    await commentRepo.archiveComment(ORG_A, stale.id);
    await searchRepo.upsertSearchDocument(ORG_A, "issue", doomed.id, "DoomedIssue", pa.id);
    await searchRepo.upsertSearchDocument(ORG_A, "project", archivedProject.id, "Gone Proj", archivedProject.id);
    const { getDb, searchIndex } = await import("@/server/db");
    getDb().insert(searchIndex).values({ id: "dupe1", orgId: ORG_A, subjectKind: "issue", subjectId: long.id, projectId: null, content: "LongDiscussion stale", indexedAt: "2020-01-01T00:00:00.000Z" }).run();
    await searchRepo.deleteSearchDocument(ORG_A, "issue", (await issueRepo.listIssues({ orgId: ORG_A, limit: 100, cursor: null })).items.at(-1)!.id);

    const bBefore = await searchRepo.countIndexed(ORG_B);
    const r1 = await runSearchReindexJob(ORG_A);
    const count1 = await searchRepo.countIndexed(ORG_A);
    const r2 = await runSearchReindexJob(ORG_A);
    const count2 = await searchRepo.countIndexed(ORG_A);
    expect(r1.failed).toBe(0);
    expect(r2.failed).toBe(0);
    // 1 project + 233 issues (230+long+thread) + 230 long comments + reply + nested
    expect(count1).toBe(1 + 232 + 230 + 2);
    expect(count2).toBe(count1);
    expect(await searchRepo.countIndexed(ORG_B)).toBe(bBefore);
    expect(await hits(ORG_A, "BulkIssue 0", ["issue"])).toBe(1);
    expect(await hits(ORG_A, "BulkIssue ")).toBe(230);
    expect(await hits(ORG_A, "LongComment 0", ["comment"])).toBe(1);
    expect(await hits(ORG_A, "LongComment ")).toBe(230);
    expect(await hits(ORG_A, "LongDiscussion")).toBe(1);
    expect(await hits(ORG_A, "SilentlyDeleted")).toBe(0);
    expect(await hits(ORG_A, "Doomed")).toBe(0);
    expect(await hits(ORG_A, "Gone Proj")).toBe(0);
    expect(await hits(ORG_A, "ParentMarker")).toBe(0);
    expect(await hits(ORG_A, "ReplyMarker")).toBe(1);
    expect(await hits(ORG_A, "NestedMarker")).toBe(1);
    void nested;
  });
});
EOF
